var a=`1236-pastelon-de-platano-maduro`;var o=`world-1236`;var i=`DO`;var t=`central-america-caribbean`;var r=8;var l=80;var s={en:`Pastelón de Plátano Maduro`,ua:`Пастелон зі стиглих плантанів`};var d={en:`Pastelón de Plátano Maduro is a dish from Dominican Republic featuring plantain, ground beef, yellow onion, garlic. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Пастелон зі стиглих плантанів, страва кухні країни Домініканська Республіка з такими основними складниками: плантан, яловичий фарш, жовта цибуля, часник. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var u=[{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 16 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 16 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:16,i:[[`plantain`,950,`g`],[`canola-oil`,120,`ml`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:17,i:[[`ground-beef`,620,`g`],[`yellow-onion`,170,`g`],[`garlic`,4,`clove`],[`tomato`,280,`g`]]},{en:`Layer the previously prepared components evenly inside a baking dish, serving mold or plate appropriate to the recipe; smooth the surface and avoid mixing the layers.`,ua:`Рівномірно викладіть підготовлені компоненти шарами у формі для запікання, подавання чи на тарілці відповідно до страви; вирівняйте поверхню, не змішуючи шари.`,t:[`layered-assembly`],m:12,i:[[`mozzarella`,260,`g`],[`chicken-egg`,3,`pcs`]]},{en:`Bake the shaped or assembled mixture in a preheated oven for about 35 minutes until set and cooked through.`,ua:`Випікайте сформовану або складену масу в розігрітій духовці приблизно 35 хвилин до готовності.`,t:[`baking`],m:35,i:[]}];var p={slug:a,id:o,country:`DO`,region:t,servings:8,minutes:80,title:s,text:d,steps:u};export{i as country,p as default,o as id,l as minutes,t as region,r as servings,a as slug,u as steps,d as text,s as title};